 w:["$P(X=3)=\\binom{6}{3}0{,}7^3\\,0{,}3^3=20\\cdot 0{,}343\\cdot 0{,}027=0{,}185$.",
    "$P(X=3)=\\binom{6}{3}0.7^3\\,0.3^3=20\\cdot 0.343\\cdot 0.027=0.185$."],
 x:[["Passer ikke; $20\\cdot 0{,}343\\cdot 0{,}027=0{,}185$.","Does not fit; $20\\cdot 0.343\\cdot 0.027=0.185$."],
    ["Passer ikke; $20\\cdot 0{,}343\\cdot 0{,}027=0{,}185$.","Does not fit; $20\\cdot 0.343\\cdot 0.027=0.185$."],
    null,
    ["Passer ikke; $20\\cdot 0{,}343\\cdot 0{,}027=0{,}185$. (Uten binomialkoeffisienten får man $0{,}0093$.)","Does not fit; $20\\cdot 0.343\\cdot 0.027=0.185$. (Without the binomial coefficient you get $0.0093$.)"],
    ["Passer ikke; $20\\cdot 0{,}343\\cdot 0{,}027=0{,}185$.","Does not fit; $20\\cdot 0.343\\cdot 0.027=0.185$."],
    ["Passer ikke; $20\\cdot 0{,}343\\cdot 0{,}027=0{,}185$.","Does not fit; $20\\cdot 0.343\\cdot 0.027=0.185$."]],
 f:["$P(X=x)=\\binom{n}{x}p^x(1-p)^{n-x}$","$P(X=x)=\\binom{n}{x}p^x(1-p)^{n-x}$"],
